/*
 * 投影引擎（js/projections.js）
 *
 * 解决的问题：国产矢量数据几乎都是**投影坐标**（CGCS2000 高斯-克吕格 / UTM /
 * 阿尔伯斯 / 兰勃特 …），不是经纬度。原导入器把投影坐标当经纬度用，
 * 结果就是「文件导入了、图层也出来了，但位置在印度洋/几内亚湾，完全没法用」。
 *
 * 本模块：
 *   - 解析 .prj（ESRI WKT）、QGIS 的 WKT1/WKT2、PROJ 字符串、EPSG 码
 *   - 识别 CGCS2000 / Xi'an80 / Beijing54 / Krasovsky / WGS84 / NAD83 等基准
 *   - 逆投影到 WGS84 经纬度
 *
 * 依赖：vendor/proj4/proj4.js（MIT）
 *
 * 导出：window.LEProj = {
 *   parse(wktOrDef),             // → { ok, def, name, kind, error }
 *   isGeographic(wkt),           // 判定是否已是经纬度
 *   toWgs84(wkt, x, y) → [lon,lat] | null
 *   transformMany(wkt, coords) → [[lon,lat], ...]
 *   describe(wkt) → 中文说明
 * }
 */
